fn idx(x: i32, y: i32, w: i32) -> i32 {
    y * w + x
}

fn col(i: i32, w: i32) -> i32 {
    i % w
}

fn row(i: i32, w: i32) -> i32 {
    i / w
}

fn wrapn(v: i32, n: i32) -> i32 {
    let m: i32 = v % n;
    if m < 0 { m + n } else { m }
}

fn dims() -> i32 {
    (256 << 16) | 160
}

fn frame(t: i32) {
    host::display::clear(0x000000);
    host::display::draw_string(8, 8, "LIB GRID", 0xffffff, 2);
    host::display::draw_string(8, 30, "IDX COL ROW WRAPN", 0x00ff66, 1);
    let mut i: i32 = 0;
    while i < 12 {
        let x: i32 = 12 + col(i, 4) * 58;
        let y: i32 = 48 + row(i, 4) * 34;
        host::display::fill_rect(x, y, 52, 28, 0x202030);
        host::display::draw_number(x + 6, y + 8, i, 0xffff00, 1);
        i = i + 1;
    }
    let hot: i32 = wrapn(t / 20, 12);
    let hx: i32 = 12 + col(hot, 4) * 58;
    let hy: i32 = 48 + row(hot, 4) * 34;
    host::display::fill_rect(hx, hy, 52, 28, 0x00ff66);
    host::display::draw_number(hx + 6, hy + 8, hot, 0x000000, 1);
    host::display::present();
}
